def final_grades(submissions: Iterable[Submission], assignments: Dict[str, Assignment],
                 policy: LatePolicy, roster: Optional[Iterable[str]] = None) -> Dict[Tuple[str, str], float]:
    """Compute final grades per (student_id, assignment).
    Applies late policy, validates scores, and selects the highest adjusted score per student/assignment.
    If a roster is provided, ensures every student in the roster has an entry for each assignment,
    using 0.0 when there is no submission.
    """
    # Map to best adjusted score
    best: Dict[Tuple[str, str], float] = {}
    for sub in submissions:
        # Validate assignment exists
        if sub.assignment not in assignments:
            raise ValueError(f"unknown assignment {sub.assignment}")
        assignment_obj = assignments[sub.assignment]
        # Validate raw score bounds
        if not (0 <= sub.score <= assignment_obj.max_score):
            raise ValueError(f"score {sub.score} out of bounds for assignment {sub.assignment}")
        # Compute adjusted score
        penalty = policy.penalty(sub.submitted_at, assignment_obj.deadline)
        adjusted = sub.score * (1 - penalty)
        key = (sub.student_id, sub.assignment)
        # Keep highest adjusted score
        if key not in best or adjusted > best[key]:
            best[key] = adjusted
    # Round scores to two decimals
    final: Dict[Tuple[str, str], float] = {k: round(v, 2) for k, v in best.items()}
    # Handle roster inclusion
    if roster is not None:
        for student in roster:
            for assignment_name in assignments.keys():
                key = (student, assignment_name)
                if key not in final:
                    final[key] = 0.0
    return final

